const input = $('Webhook: /api/v1/live-leverage').first().json.body;
const rawArgs = input.message?.toolCalls?.[0]?.function?.arguments;
const args = typeof rawArgs === 'string' ? JSON.parse(rawArgs) : (rawArgs || input);

const vendorQuote = Number(args.vendor_quote) || 0;
const dbResult = $input.first()?.json;
const lowestVerified = dbResult?.pricing?.final_negotiated_price || null;

// Compute aggressive yet realistic counter-anchor target
let batnaPrice = lowestVerified;
if (!batnaPrice || batnaPrice <= 0) {
  batnaPrice = Math.round(vendorQuote * 0.90);
}

const counterOffer = Math.round(Math.min(batnaPrice, vendorQuote * 0.93));
const formattedBATNA = counterOffer.toLocaleString('en-IN');

const tacticalScript = `We have a verified quote at ₹${formattedBATNA} for the exact spec. Can you beat that if we confirm today?`;

return {
  json: {
    results: [
      {
        toolCallId: input.message?.toolCalls?.[0]?.id || 'tc_batna',
        result: {
          counter_offer: counterOffer,
          competitor_price: batnaPrice,
          leverage_script: tacticalScript,
          status: 'success'
        }
      }
    ]
  }
};
